    if (!failed.length && !measurement.timedOut && measurement.integrity && ![1, 2, 3, 4].includes(measurement.exitCode)) return [];
    // A generated file can fail to load before its named test is registered.
    // Associate diagnostics by its unique artifact file; verification still requires the exact test name.
    let ids = [...new Set(failed.map((outcome) => report.tests.find((test) => test.approved && outcome.file === testFile(test.id, report.runtime))?.id || outcome.node))].sort((a, b) => Number(report.tests.some(test => test.id === b)) - Number(report.tests.some(test => test.id === a)));
    if (!ids.length) ids.push('environment');
    const deferred = ids.slice(40).map(testId => ({ testId, phase, category: 'uncertain' as const, reason: 'More than 40 failures in this phase. Full execution is saved; this failure was not submitted for model diagnosis and cannot authorize repair.', quote: '', executionQuote: '', evidence: [] }));
    if (deferred.length) {
      report.diagnoses.push(...deferred);
      report.limitations.push(`${phase}: ${deferred.length} failures remain explicitly undiagnosed after the 40-failure model-context limit.`);
      ids = ids.slice(0, 40);
    }
    const evidenceSnapshot = { ...snapshot, files: { ...snapshot.files, ...Object.fromEntries(report.tests.map((test) => [testFile(test.id, report.runtime), test.code])) } };
    const titles = { collection: 'Diagnose test collection failures', baseline: 'Diagnose existing-test failures', execution: 'Diagnose failures before refinement', remeasurement: 'Diagnose re-measured failures' };
    const failedTests = report.tests.filter(test => test.approved && ids.includes(test.id));
    const affected = report.analysis!.behaviors.filter(behavior => failedTests.some(test => test.behaviorId === behavior.id) || behavior.existingTests.some(node => ids.includes(node)));
    const traceFiles = Object.keys(evidenceSnapshot.files).filter(file => measurement.log.includes(file) || failed.some(outcome => outcome.file === file || outcome.message.includes(file)));
    const selectedFailures = failed.filter(outcome => ids.includes(report.tests.find(test => test.approved && outcome.file === testFile(test.id, report.runtime))?.id || outcome.node));
    const result = await stage(titles[phase], () => ask(diagnosisSchema, diagnosisTask, { ...focusedContext(affected.map(behavior => behavior.id), traceFiles, evidenceSnapshot.files), tests: failedTests.map(test => ({ id: test.id, behaviorId: test.behaviorId, functionName: test.functionName, purpose: test.purpose, quote: test.quote, file: testFile(test.id, report.runtime) })), phase, failedTestIds: ids, measurement: { ...measurement, outcomes: selectedFailures, outcomeScope: { totalFailures: failed.length, included: selectedFailures.length, omitted: failed.length - selectedFailures.length } } }, report.model, signal));
    const normalized = result.decisions.map(decision => ({ ...decision, testId: diagnosisTestId(decision.testId, ids, report, measurement) }));
    const decisions = ids.map((testId) => {
      const candidates = normalized.filter((decision) => decision.testId === testId).map(decision => ({ ...decision, testId }));
      const decision = candidates[0];
      const test = report.tests.find((test) => test.id === testId);
      const logs =[measurement.log, ...failed.filter((outcome) => !test || outcome.file === testFile(test.id, report.runtime)).map((outcome) => outcome.message)];
      const executionSupported = decision && decision.executionQuote.trim() && logs.some((log) => log.includes(decision.executionQuote));
      // The violated contract and the failing code may belong to another requirement than the test's own
      // behavior (specifications cross-reference each other); both must still be quoted verbatim.
      const codeAndTest = decision?.evidence.some((item) => sourceFile(item.file) && snapshot.files[item.file] !== undefined && !snapshot.nodes.some((node) => node.startsWith(item.file + '::'))) && decision.evidence.some((item) => item.file === (test ? testFile(test.id, report.runtime) : testId.split('::')[0]));
      const grounded = decision && candidates.length === 1 && (decision.category !== 'generated_test_error' || !!test && ['execution', 'remeasurement'].includes(phase)) && validEvidence(decision.evidence, evidenceSnapshot) && (decision.category === 'uncertain' || executionSupported && (decision.category === 'environment_failure' || decision.quote.trim() && report.rules.some((rule) => rule.text.includes(decision.quote)) && (!['generated_test_error', 'potential_implementation_defect'].includes(decision.category) || codeAndTest)));
      return grounded ? decision : { testId, category: 'uncertain' as const, reason: 'Diagnosis lacks unique, grounded requirement/code/test/execution evidence; refinement is blocked.', quote: '', executionQuote: '', evidence: [] };
    });
    report.proposedDiagnoses = [...(report.proposedDiagnoses || []), ...result.decisions.map((decision) => ({ ...decision, phase }))];
    report.diagnoses.push(...decisions.map((decision) => ({ ...decision, phase })));
    return decisions;
  }
  const diagnoses = await diagnose();
  // Exactly one evidence-supported improvement action per run.
  const repairable = report.tests.filter((test) => features.failureDiagnosis
    ? diagnoses.some((decision) => decision.testId === test.id && decision.category === 'generated_test_error')
    : test.approved && measured.outcomes.some(outcome => outcome.file === testFile(test.id, report.runtime) && ['failed', 'error'].includes(outcome.status)));
  const rejected = report.tests.filter(test => !test.approved && behaviorFor(test)?.issue === 'none' && test.reviewDecision?.supported === false && test.quote.trim() && test.reviewDecision.quote.trim() && ruleFor(test)?.text.includes(test.quote) && ruleFor(test)?.text.includes(test.reviewDecision.quote));
  let improveReason = '', eligible: PythonTest[] = [];
  const gapTargets = report.analysis.behaviors.filter(behavior => behavior.issue === 'none' && !report.tests.some(test => test.behaviorId === behavior.id));
  const uncoveredExamples = report.rules.flatMap(rule => {
    const coverage = requirementCoverage(report, rule.id);
    return coverage.reviewed && !coverage.complete && coverage.missingExamples.length ? [{ ruleId: rule.id, examples: coverage.missingExamples }] : [];
  });
  const exampleTargets = report.analysis.behaviors.filter(behavior => behavior.issue === 'none' && uncoveredExamples.some(item => item.ruleId === behavior.ruleId));
  let mutationFiles: string[] = [];
  const attemptedMutationReviews = new Set<string>();
  const reviewMutations = (phase: string) => reviewSurvivingMutations(report, (pairs, batch) => stage(`${phase} mutation relevance batch ${batch}`, () => ask(relevanceSchema, mutationReviewTask, mutationReviewContext(report, snapshot.files, pairs), report.model, signal)), attemptedMutationReviews);
  async function measureMutations(name: string) {
    if (!configuredFeatures.mutationGuidance) return false;
    // Python runs mutate Python sources only; frontend files are checked by browser tests without mutation.
    mutationFiles = [...new Set(report.tests.filter(test => test.approved && behaviorFor(test)?.issue === 'none').flatMap(test => behaviorFor(test)!.files))].filter(file => !projectTestFile(file, snapshot.nodes) && (report.runtime === 'node' || file.endsWith('.py')));
    if (!mutationFiles.length) return false;
    report.mutations.push(await stage(name, () => mutateProject(root, mutationFiles, signal, image, undefined, snapshot.nodes)));
    return true;
  }
  if (repairable.length) {
    eligible = repairable;
    improveReason = features.failureDiagnosis ? 'Repair only diagnosed generated-test errors; preserve all other failures.' : 'B2 baseline: attempt to repair every failed generated artifact using the recorded execution feedback, without classifying the failure cause. Keep the original requirement as the oracle; the same admission checks still apply.';
  }
  else if (exampleTargets.length) {
    improveReason = 'Add NEW tests for the verbatim original examples or boundaries in context.uncoveredExamples. Preserve all existing artifacts and valid failures. Use the assigned behavior and claim gapIndexes only when they match the actual listed gap; an explicit example omitted from the plan may use an empty gapIndexes list. Do not invent further requirements.';
  }
  else if (gapTargets.length) {
    improveReason = 'Add NEW test artifacts only for supported behaviors without a generated proposal. Check the original contract and assigned gaps. Preserve all existing artifacts, including blocked proposals without an eligible rejection review; invent no missing contract and bypass no review.';
  }
  else if (mutationExecutionReady(report, measured)) {
    if (await measureMutations('Measure selected mutations')) {
      if (!rejected.length) await reviewMutations('Review surviving');
      if (report.relevance.some((decision) => decision.grounded && decision.relevant && report.analysis!.behaviors.some(behavior => behavior.id === decision.behaviorId && behavior.issue === 'none'))) improveReason = 'Add contract-grounded tests for reviewed relevant surviving mutants; keep all existing tests. Cover the reviewed independent behavior gaps rather than repeating checks for only the earliest mutant IDs. Assert only supported expectations, without incidental timezone identity, exact message text or precision requirements.';
    }
  }
  if (!repairable.length && rejected.length) {
    eligible = rejected;
    improveReason = 'Correct only the explicitly rejected generated artifacts using their recorded review reasons and original contracts. Keep their IDs and behavior links. Remove unsupported extra obligations and use contract-supported assertions for every claimed gap. Preserve all approved tests and valid failing assertions; leave genuinely unspecified behavior unresolved. Every replacement must pass the same review again.';
  }
  if (improveReason) {
    const attempt = beginAttempt('improvement', improveReason);
    const candidate = await stage('Improve tests once', () => ask(testsSchema, improveReason + ' Return only replacement artifacts with the SAME IDs for context.eligible artifacts, or NEW T IDs for additional supported gap or mutation checks. Never alter correct failing assertions. Every change will be reviewed again.', { ...context, analysis: report.analysis, tests: report.tests, eligible, uncoveredExamples, diagnoses: report.diagnoses, measurement: measurementContext(measured, testContext.nodes), mutations: report.mutations, relevance: report.relevance }, report.model, signal));
    attempt.tests = structuredClone(candidate.tests);
    const changes = candidate.tests.filter((test) => eligible.length ? eligible.some((old) => old.id === test.id && old.behaviorId === test.behaviorId) : !report.tests.some((old) => old.id === test.id) && (gapTargets.some(behavior => behavior.id === test.behaviorId) || exampleTargets.some(behavior => behavior.id === test.behaviorId) || report.relevance.some((decision) => decision.grounded !== false && decision.relevant && decision.behaviorId === test.behaviorId)));
    report.improvementProposal = await reviewed(changes, attempt, candidate.tests.filter(test => !changes.includes(test)));
    const accepted = report.improvementProposal.filter((test) => test.approved);
    if (accepted.length) {
      const before = report.tests;
      report.tests = [...before.filter((test) => !accepted.some((replacement) => replacement.id === test.id)), ...accepted];
      report.improvements.push({ reason: improveReason, before, after: report.tests });
      await writeTests(root, report.tests);
      attempt.status = 'applied';
      measured = await stage('Re-measure improved tests', measure);
      await diagnose(measured, 'remeasurement');
      if (mutationExecutionReady(report, measured) && report.mutations.length) report.mutations.push(await stage('Re-measure selected mutations', () => mutateProject(root, report.mutations[0].scope?.file || report.mutations[0].mutants[0]?.file || mutationFiles[0], signal, image, report.mutations[0].scope?.functions, snapshot.nodes, report.mutations[0].scope?.kind === 'executed_lines' ? report.mutations[0].scope.lines : undefined)));
      // Repaired tests have not been mutation-tested yet; measure them before they can earn Verified.
      else if (!report.mutations.length && mutationExecutionReady(report, measured)) await measureMutations('Measure selected mutations after repair');
    }
  }
  await reviewMutations('Review remaining');
  updateStates(report);
  report.stopReason = improveReason
    ? report.testAttempts?.at(-1)?.status === 'applied'
      ? 'The single improvement was applied and re-measured. No further improvement is allowed in this run; inspect the latest outcomes and unresolved requirements.'
      : 'The improvement was not admitted. Earlier approved tests remain active; the single improvement budget is exhausted.'
    : measured.outcomes.some(outcome => ['failed', 'error'].includes(outcome.status))
      ? 'Failing checks were retained because no supported generated-test repair was selected. Inspect the failure diagnoses before changing assertions.'
      : 'No further improvement was selected under this run\'s policy. Recorded passes do not resolve any remaining verification gaps.';
  await complete();
}

// Configured capabilities, not claims that every stage completed in a given run.
export const agentVariants = {
  B0: { name: 'Direct LLM', retrievedEvidence: false, requirementAnalysis: false, executionFeedback: false, mutationGuidance: false, failureDiagnosis: false },
  B1: { name: 'Grounded Test Generator', retrievedEvidence: true, requirementAnalysis: false, executionFeedback: false, mutationGuidance: false, failureDiagnosis: false },
  B2: { name: 'Full Agent without Failure Diagnosis', retrievedEvidence: true, requirementAnalysis: true, executionFeedback: true, mutationGuidance: true, failureDiagnosis: false },
  B3: { name: 'Full Verification Agent', retrievedEvidence: true, requirementAnalysis: true, executionFeedback: true, mutationGuidance: true, failureDiagnosis: true },
} as const;

export type AgentVariant = keyof typeof agentVariants;
export type ConfiguredAgentFeatures = { [Key in keyof typeof agentVariants.B3]: Key extends 'name' ? string : boolean };

import { createHash } from 'node:crypto';
import { posix } from 'node:path';

// A mapped file alone is insufficient when a recorded local dependency remains unseen.
export function hasUninspectedContext(selections: { selectedFiles: string[]; complete: boolean; dependencyLinks?: { from: string; to: string }[] }[] | undefined, mapped: string[]) {
  if (!selections?.some(selection => !selection.complete)) return false;
  if (!mapped.length) return true;
  const inspected = new Set(selections.flatMap(selection => selection.selectedFiles));
  const links = selections.flatMap(selection => selection.dependencyLinks || []);
  const pending = [...mapped], visited = new Set<string>();
  while (pending.length) {
    const file = pending.pop()!;
    if (visited.has(file)) continue;
    visited.add(file);
    if (!inspected.has(file)) return true;
    pending.push(...links.filter(link => link.from === file).map(link => link.to));
  }
  return false;
}

// Static local-import candidates only. No code is evaluated and no external module is fetched.
// Dynamic imports, aliases and runtime configuration can still require uninspected files.
export function localDependencyGraph(files: Record<string, string>) {
  const graph = new Map<string, string[]>();
  const has = (file: string) => Object.hasOwn(files, file);
  for (const [file, text] of Object.entries(files)) {
    const dependencies = new Set<string>();
    function resolve(base: string, python: boolean) {
      base = posix.normalize(base);
      if (base === '..' || base.startsWith('../') || posix.isAbsolute(base)) return;
      const candidates = python ? [base + '.py', posix.join(base, '__init__.py')] : [base, ...['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.json', '.css'].map(ext => base + ext), ...['.ts', '.tsx', '.js', '.mjs', '.cjs'].map(ext => posix.join(base, 'index' + ext))];
      // NodeNext TypeScript sources commonly import the emitted .js filename.
      if (!python && /\.[cm]?js$/.test(base)) candidates.push(base.replace(/\.([cm]?)js$/, '.$1ts'), base.replace(/\.js$/, '.tsx'));
      const found = candidates.find(has);
      if (!found) return;
      dependencies.add(found);
      if (python) for (let directory = posix.dirname(found); directory !== '.'; directory = posix.dirname(directory)) {
        const init = posix.join(directory, '__init__.py');
        if (has(init)) dependencies.add(init);
      }
    }
    if (file.endsWith('.py')) {
      const roots = [''];
      for (let directory = posix.dirname(file); directory !== '.'; directory = posix.dirname(directory)) roots.push(directory);
      for (const match of text.matchAll(/^\s*from\s+([.\w]+)\s+import\s+(\([^)]*\)|[^\n;]+)/gm)) {
        const specifier = match[1], dots = /^\.+/.exec(specifier)?.[0].length || 0;
        const bases = dots ? [posix.join(posix.dirname(file), ...Array(dots - 1).fill('..'), specifier.slice(dots).replaceAll('.', '/'))] : roots.map(root => posix.join(root, specifier.replaceAll('.', '/')));
        for (const base of bases) {
          resolve(base, true);
          for (const name of match[2].replace(/[()]/g, '').split(',')) {
            const child = /^\s*(\w+)/.exec(name)?.[1];
            if (child) resolve(posix.join(base, child), true);
          }
        }
      }
      for (const match of text.matchAll(/^\s*import\s+([^\n;]+)/gm)) for (const name of match[1].split(',')) {
        const specifier = /^\s*([\w.]+)/.exec(name)?.[1];
        if (specifier) for (const root of roots) resolve(posix.join(root, specifier.replaceAll('.', '/')), true);
      }
    } else if (/\.[cm]?[jt]sx?$/.test(file)) {
      const specs = [...text.matchAll(/\b(?:import|export)\s+(?:[^;]*?\s+from\s*)?["']([^"']+)["']/g), ...text.matchAll(/\b(?:require|import)\s*\(\s*["']([^"']+)["']\s*\)/g)];
      for (const match of specs) if (match[1].startsWith('.')) resolve(posix.join(posix.dirname(file), match[1]), false);
    }
    graph.set(file, [...dependencies].filter(dependency => dependency !== file).sort());
  }
  return graph;
}

// Keep whole original files: citation line numbers must never shift after retrieval.
export function selectProjectContext(files: Record<string, string>, query: string, required: string[] = [], budget = 180_000, focused = false) {
  const entries = Object.entries(files), bytes = (text: string) => Buffer.byteLength(JSON.stringify(text));
  const totalBytes = entries.reduce((sum, [file, text]) => sum + bytes(file) + bytes(text), 0);
  const terms = [...new Set(query.toLowerCase().split(/[^a-z0-9_]+/).filter(term => term.length > 2))];
  const ranked = entries.map(([file, text]) => {
    const path = file.toLowerCase(), content = text.toLowerCase();
    const score = terms.reduce((sum, term) => sum + (path.includes(term) ? 8 : 0) + (content.includes(term) ? 1 : 0), 0);
    return { file, text, size: bytes(file) + bytes(text), score, required: required.includes(file) };
  }).sort((a, b) => Number(b.required) - Number(a.required) || b.score - a.score || a.file.localeCompare(b.file));
  const graph = localDependencyGraph(files), byFile = new Map(ranked.map(item => [item.file, item]));
  const selected: Record<string, string> = {};
  let selectedBytes = 0;
  function include(file: string) {
    if (Object.hasOwn(selected, file)) return true;
    const item = byFile.get(file);
    if (!item || selectedBytes + item.size > budget) return false;
    selected[file] = item.text; selectedBytes += item.size; return true;
  }
  // Reserve explicitly mapped files before allowing their dependencies to consume the budget.
  for (const item of ranked.filter(item => item.required)) include(item.file);
  const dependencyLinks = new Map<string, { from: string; to: string }>(), expanded = new Set<string>();
  function expand(file: string) {
    if (expanded.has(file)) return;
    expanded.add(file);
    for (const to of graph.get(file) || []) {
      dependencyLinks.set(JSON.stringify([file, to]), { from: file, to });
      if (include(to)) expand(to);
    }
  }
  if (!focused && totalBytes <= budget) for (const [file] of entries) include(file);
  else for (const item of ranked) if (focused ? item.required : item.required || item.score > 0 || selectedBytes === 0) {
    if (include(item.file)) expand(item.file);
  }
  const omitted = ranked.filter(item => !Object.hasOwn(selected, item.file)).map(item => ({ file: item.file, bytes: item.size, sha256: createHash('sha256').update(item.text).digest('hex'), required: item.required }));
  return { files: !focused && totalBytes <= budget ? files : selected, scope: { totalBytes, selectedBytes, budget, selectedFiles: Object.keys(selected), omitted, complete: omitted.length === 0, dependencyLinks: [...dependencyLinks.values()] } };
}

import { createHash } from 'node:crypto';

export const projectTextFile = (name: string) => /\.(py|[cm]?[jt]sx?|md|rst|txt|toml|cfg|ini|json|lock|html?|css|csv|xml|ya?ml|metadata|svg)$/.test(name) || /(?:^|\/)(?:LICENSE(?:[.][\w-]+)?|COPYING|NOTICE)$/.test(name);
export const projectAssetFile = (name: string) => /(?:^|\/)(?:tests?|fixtures?|data|assets?|static|shared|resources?|templates?)\//.test(name) && !/\.(?:pyc|pyo|so|dylib|dll|exe|sh|bat|ps1|zip|tar|gz|whl)$/.test(name);

// Keep legacy all-text fingerprints unchanged. Binary assets bind exact bytes,
// without decoding them or including their contents in model context.
export function projectFingerprint(entries: [string, Buffer][]) {
  const values = entries.map(([name, bytes]) => [name, projectTextFile(name)
    ? new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes)
    : { bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') }]);
  return createHash('sha256').update(JSON.stringify(values.sort((a, b) => String(a[0]) < String(b[0]) ? -1 : String(a[0]) > String(b[0]) ? 1 : 0))).digest('hex');
}

import type { Measurement } from './python-types';

/** Select a bounded model catalog; this never selects or truncates execution. */
export function selectTestContext(nodes: string[], query: string, maxNodes = 200, byteBudget = 24_000) {
  const terms = [...new Set(query.toLowerCase().split(/[^a-z0-9]+/).filter(term => term.length > 2))];
  const groups = new Map<string, { node: string; score: number }[]>();
  for (const node of nodes) {
    const score = terms.reduce((sum, term) => sum + (node.toLowerCase().includes(term) ? 1 : 0), 0);
    const file = node.split('::')[0];
    if (!groups.has(file)) groups.set(file, []);
    groups.get(file)!.push({ node, score });
  }
  const ranked = [...groups.values()].map(group => group.sort((a, b) => b.score - a.score || a.node.localeCompare(b.node))).sort((a, b) => b[0].score - a[0].score || a[0].node.localeCompare(b[0].node));
  const selected: string[] = [];
  let bytes = 0;
  // Round-robin across files avoids one heavily parameterized module consuming everything.
  for (let index = 0; selected.length < maxNodes && ranked.some(group => group[index]); index++) {
    for (const group of ranked) {
      const item = group[index];
      if (!item) continue;
      const size = Buffer.byteLength(JSON.stringify(item.node));
      if (bytes + size > byteBudget || selected.length >= maxNodes) continue;
      selected.push(item.node); bytes += size;
    }
  }
  return { nodes: selected, scope: { totalNodes: nodes.length, selectedNodes: selected.length, omittedNodes: nodes.length - selected.length, byteBudget, selectedBytes: bytes, purpose: 'Model context only. The execution baseline uses the full collected suite.' } };
}

export function measurementContext(measurement: Measurement | undefined, relevant: string[] = []) {
  if (!measurement) return undefined;
  const wanted = new Set(relevant);
  const candidates = measurement.outcomes.filter(item => ['failed', 'error'].includes(item.status) || wanted.has(item.node) || item.file.startsWith('reqtest_generated/'));
  const selected = candidates.sort((a, b) => Number(['failed', 'error'].includes(b.status)) - Number(['failed', 'error'].includes(a.status)) || Number(b.file.startsWith('reqtest_generated/')) - Number(a.file.startsWith('reqtest_generated/'))).slice(0, 200);
  return { ...measurement, outcomes: selected,
    outcomeScope: { total: measurement.outcomes.length, included: selected.length, omitted: measurement.outcomes.length - selected.length,
      counts: Object.fromEntries(['passed', 'failed', 'error', 'skipped'].map(status => [status, measurement.outcomes.filter(item => item.status === status).length])),
      complete: selected.length === measurement.outcomes.length, note: 'Only listed outcomes are shown to the model. Full exact outcomes remain in the saved measurement.' } };
}

import type { Measurement } from './python-types';

/** Exact original log lines behind bounded provider references; no quote normalization. */
export function executionEvidence(measurement: Measurement, budget = 60_000, maxLines = 300) {
  const outcomes = [...measurement.outcomes].sort((a, b) => Number(b.file.startsWith('reqtest_generated/')) - Number(a.file.startsWith('reqtest_generated/')));
  const blocks = [...outcomes.map(outcome => ({ location: outcome.node, text: outcome.message })), { location: 'execution log', text: measurement.log }];
  const unique = new Map<string, string>();
  for (const block of blocks) for (const line of block.text.split('\n')) if (line.trim() && !unique.has(line)) unique.set(line, block.location);
  const references: { id: string; quote: string; location: string }[] = [];
  let bytes = 0;
  for (const [quote, location] of unique) {
    const item = { id: `E${references.length + 1}`, quote, location };
    const size = Buffer.byteLength(JSON.stringify(item));
    if (bytes + size > budget || references.length >= maxLines) continue;
    references.push(item); bytes += size;
  }
  return { references, scope: { totalUniqueLines: unique.size, selectedLines: references.length, omittedLines: unique.size - references.length, selectedBytes: bytes, budget, complete: references.length === unique.size } };
}

import { z } from "zod";
import type { RequirementSource, DocumentPage, RequirementDocument } from "./requirements";
import type { ProjectSetup } from "./project-setup";
import type { VerificationPolicy } from './verification-policy';
import type { AgentVariant, ConfiguredAgentFeatures } from './agent-variants';
import { sourceFile, type ProjectRuntime } from "./runtime";
const evidence = z.object({ file: z.string(), quote: z.string().min(1), line: z.number().int().min(1).optional() });
export function sourceEvidenceSchema(files: Record<string, string>) {
  const lines = Object.fromEntries(Object.entries(files).map(([file, text]) => [file, text.split('\n')]));
  return z.object({ file: z.enum(Object.keys(files)), line: z.number().int().min(1).max(Math.max(1, ...Object.values(lines).map(rows => rows.length))) })
    .superRefine((reference, context) => {
      if (!lines[reference.file]?.[reference.line - 1]?.trim()) context.addIssue({ code: 'custom', message: 'Source line is missing or blank.' });
    })
    .transform(reference => ({ ...reference, quote: lines[reference.file][reference.line - 1] }));
}
// A list of line references keeps the ones that resolve to a nonblank source line and drops the rest.
// One mistyped line number in a large response must not reject every other finding; a dropped
// reference is never replaced by a nearby line or a model-copied quotation.
export function sourceEvidenceListSchema(files: Record<string, string>, min = 0) {
  const single = sourceEvidenceSchema(files);
  const lines = Math.max(1, ...Object.values(files).map(text => text.split('\n').length));
  const reference = z.object({ file: z.enum(Object.keys(files)), line: z.number().int().min(1).max(lines) });
  return z.array(reference).min(min).transform(references => references.flatMap(item => {
    const resolved = single.safeParse(item);
    return resolved.success ? [resolved.data] : [];
