import { createOpenAI } from "@ai-sdk/openai";
import { APICallError } from "ai";
import { defaultModelResponseSeconds } from './verification-policy';

export class ModelTimeoutError extends Error {
  constructor(seconds: number) {
    super(`Model response timed out after ${seconds} seconds. Partial evidence and the consumed request are retained. Increase the model response timeout or reduce the scope before starting a new run.`);
    this.name = 'ModelTimeoutError';
  }
}

export function modelError(error: unknown) {
  const status = APICallError.isInstance(error) ? error.statusCode : undefined;
  if (status === 401) return 'OpenAI rejected the API key. Update OPENAI_API_KEY in .env.local and restart the website and worker.';
  if (status === 403 || status === 404) return 'OpenAI cannot access this model. Check its exact model ID and account permissions.';
  if (status === 429) return 'OpenAI quota or rate limit reached. Check the API account and retry later.';
  return (error instanceof Error ? error.message : 'Model request failed.').replaceAll(process.env.OPENAI_API_KEY || '\0', '[redacted]').replace(/sk-[A-Za-z0-9_*.-]+/g, '[redacted]');
}

export function options(input: { model: string; timeoutMs?: number; maxOutputTokens?: number }, signal: AbortSignal) {
  if (!process.env.OPENAI_API_KEY) throw new Error("Fill OPENAI_API_KEY in the root .env or this app's .env.local.");
  if (process.env.OPENAI_API_KEY.startsWith('sk-or-')) throw new Error('Use an OpenAI API key from platform.openai.com. Third-party API keys are not supported.');
  return {
    model: createOpenAI({ apiKey: process.env.OPENAI_API_KEY, baseURL: 'https://api.openai.com/v1' }).responses(input.model),
    // Zero explicitly disables the per-call deadline; owner cancellation remains active.
    abortSignal: (input.timeoutMs ?? defaultModelResponseSeconds * 1000) > 0 ? AbortSignal.any([signal, AbortSignal.timeout(input.timeoutMs ?? defaultModelResponseSeconds * 1000)]) : signal,
    maxRetries: 0,
    ...(input.maxOutputTokens ? { maxOutputTokens: input.maxOutputTokens } : {}),
    providerOptions: { openai: { store: false } },
  };
}

export type ProjectRuntime = "python" | "node";
export const sourceFile = (file: string) => /\.(py|[cm]?[jt]sx?)$/.test(file);
export const projectTestFile = (file: string, nodes: string[] = []) => nodes.some(node => node.split('::')[0] === file) || /(?:^|\/)(?:tests?|__tests__)\//.test(file) || /(?:^|\/)(?:conftest\.py|test_[^/]*\.py|[^/]*_test\.py|[^/]*\.(?:test|spec)\.[cm]?[jt]sx?)$/.test(file);
// A generated Python test that requests the sandbox browser fixtures.
export const browserTest = (code: string) => /def test_\w+\([^)]*\b(page|live_server)\b/.test(code);
export const testFile = (id: string, runtime: ProjectRuntime = "python") => "reqtest_generated/test_reqtest_" + id + (runtime === "node" ? ".test.ts" : ".py");

import type { Mutation, PythonReport } from './python-types';

type Mutant = Mutation['mutants'][number];
type Decision = PythonReport['relevance'][number];
export type MutationReviewPair = Mutant & { behaviorId: string };

export function mutationReviewContext(report: PythonReport, files: Record<string, string>, pairs: MutationReviewPair[]) {
  const behaviors = (report.analysis?.behaviors || []).filter(behavior => pairs.some(pair => pair.behaviorId === behavior.id));
  const inconsistencies = (report.analysis?.inconsistencies || []).filter(item => item.behaviorIds.some(id => behaviors.some(behavior => behavior.id === id)));
  const names = new Set([...pairs.map(pair => pair.file), ...behaviors.flatMap(behavior => [...behavior.files, ...behavior.existingTests.map(node => node.split('::')[0]), ...behavior.evidence.map(item => item.file)]), ...inconsistencies.flatMap(item => item.evidence.map(evidence => evidence.file))]);
  return {
    rules: report.rules,
    requirementContext: report.requirementInput?.context || '',
    analysis: { behaviors: behaviors.map(({ id, ruleId, text, category, issue, reason, files }) => ({ id, ruleId, text, category, issue, reason, files })), inconsistencies },
    files: Object.fromEntries(Object.entries(files).filter(([file]) => names.has(file))),
    mutants: [...new Map(pairs.map(({ id, file, line, diff }) => [id, { id, file, line, diff }])).values()],
    pairs: pairs.map(({ id, behaviorId }) => ({ id, behaviorId })),
    contextScope: 'All original rules and supporting requirement context are retained for cross-cutting constraints. Only mapped files are supplied; unshown dependencies are not validated. Preserve uncertainty when the evidence is insufficient.',
  };
}

export function groundedMutationDecision(report: PythonReport, mutant: Mutant, decision: Decision) {
  const behavior = report.analysis?.behaviors.find(behavior => behavior.id === decision.behaviorId);
  return decision.grounded === true && decision.mutantId === mutant.id && decision.file === mutant.file &&
    Boolean(mutant.diff.trim()) && decision.diff === mutant.diff && Boolean(decision.reason.trim()) &&
    Boolean(behavior?.files.includes(mutant.file) && decision.quote.trim() && report.rules.find(rule => rule.id === behavior.ruleId)?.text === decision.quote);
}

export const survivorLabels = {
  test_gap: 'Test gap', clarification: 'Requirement clarification',
  outside_behavior: 'Outside cited behavior', unreviewed: 'Unreviewed / unsupported',
};

export function mutationBehaviorReviews(report: PythonReport, mutant: Mutant) {
  return (report.analysis?.behaviors || []).filter(behavior => behavior.files.includes(mutant.file)).map(behavior => {
    const decisions = report.relevance.filter(decision => decision.behaviorId === behavior.id && groundedMutationDecision(report, mutant, decision));
    const decision = decisions.length === 1 ? decisions[0] : undefined;
    const category: keyof typeof survivorLabels = !decision ? 'unreviewed' : behavior.issue !== 'none' ? 'clarification' : decision.relevant ? 'test_gap' : 'outside_behavior';
    return { behavior, decision, category };
  });
}

export function survivorReviews(report: PythonReport) {
  return (report.mutations.at(-1)?.mutants || []).filter(mutant => mutant.status === 'survived').map(mutant => {
    const reviews = mutationBehaviorReviews(report, mutant);
    const category = (['unreviewed', 'test_gap', 'clarification', 'outside_behavior'] as const).find(category => reviews.some(review => review.category === category)) || 'unreviewed';
    return { mutant, reviews, decision: reviews.length === 1 ? reviews[0].decision : undefined, category };
  });
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { randomBytes, randomUUID } from "node:crypto";
import { setTimeout as delay } from "node:timers/promises";
const docker = promisify(execFile);
export async function testServices(selected: string[], signal = new AbortController().signal, scope: string = randomUUID()) {
  signal.throwIfAborted();
  const network = "reqtest-network-" + randomUUID(), containers: string[] = [], env: string[] = [];
  const cleanup = async () => {
    await Promise.all(containers.map(name => docker("docker", ["rm", "-f", "-v", name], { timeout: 10000 }).catch(() => {})));
    await docker("docker", ["network", "rm", network], { timeout: 10000 }).catch(() => {});
  };
  if (!selected.length) return { network: "none", env, cleanup: async () => {} };
  if (selected.some(service => !["postgres", "redis"].includes(service))) throw new Error("Unsupported test service.");
  // Empty networks from crashed workers are safe to reclaim after the service lifetime.
  const stale = (await docker("docker", ["network", "ls", "--filter", "label=reqtest.temporary=true", "-q"], { timeout: 10000 })).stdout.trim().split(/\s+/).filter(Boolean);
  for (const id of stale) {
    try {
      const [details] = JSON.parse((await docker("docker", ["network", "inspect", id], { timeout: 10000 })).stdout);
      if (!Object.keys(details.Containers || {}).length && Date.now() - Date.parse(details.Created) > 360000) await docker("docker", ["network", "rm", id], { timeout: 10000 });
    } catch { /* Another worker may have reclaimed this empty network. */ }
  }
  try {
    await docker("docker", ["network", "create", "--internal", "--label", "reqtest.temporary=true", "--label", "reqtest.scope=" + scope, network], { timeout: 10000 });
    signal.throwIfAborted();
    for (const service of selected) {
      signal.throwIfAborted();
      const name = "reqtest-service-" + randomUUID(), password = randomBytes(16).toString("hex");
      containers.push(name);
      const common = ["run", "-d", "--rm", "--name", name, "--label", "reqtest.temporary=true", "--label", "reqtest.scope=" + scope, "--network", network, "--network-alias", service, "--read-only", "--cap-drop=ALL", "--security-opt=no-new-privileges", "--pids-limit", "64", "--cpus", "0.5", "--memory", service === "postgres" ? "256m" : "64m", "--tmpfs", "/tmp:rw,size=128m,mode=1777", "--entrypoint", "timeout"];
      // The lifetime also bounds services left behind by a forcibly killed worker.
      const entrypoint = ["-k", "5", "300", "/usr/local/bin/docker-entrypoint.sh"];
      if (service === "postgres") {
        await docker("docker", [...common, "--user", "postgres", "--tmpfs", "/var/run/postgresql:rw,mode=1777", "-e", "PGDATA=/tmp/pgdata", "-e", "POSTGRES_USER=reqtest", "-e", "POSTGRES_DB=reqtest", "-e", "POSTGRES_PASSWORD=" + password, "postgres:17", ...entrypoint, "postgres"], { timeout: 60000 });
        env.push("DATABASE_URL=postgresql://reqtest:" + password + "@postgres:5432/reqtest");
      } else {
        await docker("docker", [...common, "--user", "redis", "--tmpfs", "/data:rw,mode=1777", "redis:7-alpine", ...entrypoint, "redis-server", "--save", "", "--appendonly", "no"], { timeout: 60000 });
        env.push("REDIS_URL=redis://redis:6379/0");
      }
      let ready = false;
      for (let attempt = 0; attempt < 60; attempt++) {
        signal.throwIfAborted();
        try {
          const { stdout } = await docker("docker", ["exec", name, ...(service === "postgres" ? ["pg_isready", "-h", "127.0.0.1", "-U", "reqtest", "-d", "reqtest"] : ["redis-cli", "ping"])], { timeout: 3000 });
          if (service === "postgres" || stdout.trim() === "PONG") { ready = true; break; }
        } catch {}
        await delay(500, undefined, { signal });
      }
      if (!ready) throw new Error("The disposable " + service + " service did not become ready. Check Docker and the service image.");
    }
    signal.throwIfAborted();
    return { network, env, cleanup };
  } catch (error) { await cleanup(); throw error; }
}

import { testFile } from "./runtime";
import { z } from 'zod';
import type { Measurement, PythonReport } from './python-types';

const finding = z.object({ id: z.string(), ruleId: z.string(), description: z.string() });
export const goldSchema = z.object({
  reviewed: z.boolean(), reviewer: z.string(),
  issues: z.array(finding), inconsistencies: z.array(finding),
  behaviors: z.array(finding.extend({ initialGap: z.boolean() })).min(1),
  fault: z.object({ id: z.string(), file: z.string(), before: z.string().min(1), after: z.string().min(1) }).optional(),
}).refine((gold) => [gold.issues, gold.inconsistencies, gold.behaviors].every((items) => new Set(items.map((item) => item.id)).size === items.length), 'Reference IDs must be unique within each category.');
const reviewedFinding = z.object({ id: z.string(), match: z.string().nullable(), evidenceSupported: z.boolean().nullable() });
const category = z.enum(['generated_test_error', 'requirement_ambiguity', 'potential_implementation_defect', 'environment_failure', 'uncertain']);
export const reviewSchema = z.object({
  reviewed: z.boolean(), reviewer: z.string(),
  reportId: z.string().optional(), sourceFingerprint: z.string().optional(), requirementTexts: z.array(z.string()).optional(),
  validOutcome: z.boolean().nullable(),
  issues: z.array(reviewedFinding), gaps: z.array(reviewedFinding), inconsistencies: z.array(reviewedFinding),
  coverage: z.array(z.object({ id: z.string(), beforeNodes: z.array(z.string()), afterNodes: z.array(z.string()) })),
  diagnoses: z.array(z.object({ testId: z.string(), phase: z.enum(['collection', 'baseline', 'execution']).optional(), expected: category.nullable(), evidenceSupported: z.boolean().nullable() })),
  mutants: z.array(z.object({ attempt: z.number().int().min(0), id: z.string(), relevant: z.boolean().nullable(), equivalent: z.boolean().nullable() })),
});
export type Gold = z.infer<typeof goldSchema>;
export type Review = z.infer<typeof reviewSchema>;
export type FaultProbe = { id: string; beforeDetected: boolean | null; afterDetected: boolean | null; corrected: Measurement[] };
export const ratio = (numerator: number, denominator: number) => denominator ? numerator / denominator : null;
const metrics = (tp: number, fp: number, fn: number) => ({ tp, fp, fn, precision: ratio(tp, tp + fp), recall: ratio(tp, tp + fn), f1: ratio(2 * tp, 2 * tp + fp + fn) });
const covered = (nodes: string[], measurement?: Measurement) => !!nodes.length && !!measurement?.integrity && !measurement.timedOut && nodes.every((node) => measurement.outcomes.some((outcome) => outcome.node === node && outcome.status === 'passed'));

export function reviewTemplate(report: PythonReport, gold: Gold): Review {
  const empty = (id: string) => ({ id, match: null, evidenceSupported: null });
  const first = report.measurements[0];
  const originalTests = report.improvements[0]?.before || report.tests;
  const failures = first?.outcomes.filter((outcome) => ['failed', 'error'].includes(outcome.status)).map((outcome) => originalTests.find((test) => outcome.file === testFile(test.id, report.runtime) && outcome.name.split('[')[0] === test.functionName)?.id || outcome.node) || [];
  if (first && !failures.length && (first.timedOut || !first.integrity || [1, 2, 3, 4].includes(first.exitCode))) failures.push('environment');
  const diagnoses: Review['diagnoses'] = [];
  if (report.collection && (report.collection.timedOut || [1, 2, 3, 4].includes(report.collection.exitCode))) diagnoses.push({ testId: 'environment', phase: 'collection', expected: null, evidenceSupported: null });
  const baselineFailures = report.baseline?.outcomes.filter((outcome) => ['failed', 'error'].includes(outcome.status)).map((outcome) => outcome.node) || [];
  if (report.baseline && !baselineFailures.length && (report.baseline.timedOut || !report.baseline.integrity || [1, 2, 3, 4].includes(report.baseline.exitCode))) baselineFailures.push('environment');
  diagnoses.push(...[...new Set(baselineFailures)].map((testId) => ({ testId, phase: 'baseline' as const, expected: null, evidenceSupported: null })));
  diagnoses.push(...[...new Set(failures)].map((testId) => ({ testId, phase: 'execution' as const, expected: null, evidenceSupported: null })));
  const analysis = ['B0', 'B1'].includes(report.variant || '') ? undefined : report.analysis;
  return {
    reviewed: false, reviewer: '', reportId: report.id, sourceFingerprint: report.fingerprint, requirementTexts: report.rules.map(rule => rule.text), validOutcome: null,
    issues: (analysis?.behaviors || []).filter((behavior) => behavior.issue !== 'none').map((behavior) => empty(behavior.id)),
    gaps: (analysis?.behaviors || []).flatMap((behavior) => behavior.gaps.map((_, index) => empty(`${behavior.id}:${index}`))),
    inconsistencies: (analysis?.inconsistencies || []).map((_, index) => empty(`C${index + 1}`)),
    coverage: gold.behaviors.map((behavior) => ({ id: behavior.id, beforeNodes: [], afterNodes: [] })),
    diagnoses,
    mutants: report.mutations.flatMap((attempt, index) => attempt.mutants.map((mutant) => ({ attempt: index, id: mutant.id, relevant: null, equivalent: null }))),
  };
}

export const faultProbeSchema = z.object({
  id: z.string(), beforeDetected: z.boolean().nullable(), afterDetected: z.boolean().nullable(),
  corrected: z.array(z.object({ outcomes: z.array(z.object({ node: z.string(), file: z.string(), name: z.string(), status: z.enum(['passed', 'failed', 'error', 'skipped']), message: z.string() })), exitCode: z.number(), log: z.string(), timedOut: z.boolean(), integrity: z.boolean() })),
});

function exact(actual: string[], expected: string[]) {
  return new Set(actual).size === actual.length && actual.length === expected.length && actual.every((id) => expected.includes(id));
}
const diagnosisKey = (item: { testId: string; phase?: string }) => `${item.phase || 'execution'}:${item.testId}`;
export function validateReview(report: PythonReport, gold: Gold, review: Review) {
  const template = reviewTemplate(report, gold);
  if (review.reportId !== undefined && review.reportId !== report.id || review.sourceFingerprint !== undefined && review.sourceFingerprint !== report.fingerprint || review.requirementTexts !== undefined && JSON.stringify(review.requirementTexts) !== JSON.stringify(report.rules.map(rule => rule.text))) throw new Error('This review belongs to a different run, source snapshot or requirement set.');
  if (!review.reviewer.trim() || !gold.reviewer.trim() || review.validOutcome === null) throw new Error('Reviewed results require named reviewers and an independently assessed outcome.');
  for (const key of ['issues', 'gaps', 'inconsistencies'] as const) {
    const expected = key === 'gaps' ? gold.behaviors.filter((item) => item.initialGap) : gold[key];
    if (!exact(review[key].map((item) => item.id), template[key].map((item) => item.id)) || review[key].some((item) => item.evidenceSupported === null || item.match !== null && !expected.some((label) => label.id === item.match))) throw new Error(`Review must account for every real ${key} finding and use valid reference IDs.`);
  }
  if (!exact(review.coverage.map((item) => item.id), gold.behaviors.map((item) => item.id))) throw new Error('Coverage must include every reference behavior, including omitted behaviors.');
  if (!exact(review.diagnoses.map(diagnosisKey), template.diagnoses.map(diagnosisKey)) || review.diagnoses.some((item) => item.expected === null || item.evidenceSupported === null)) throw new Error('Every collection, baseline and initial execution failure needs an independent diagnosis annotation.');
  const mutantKey = (item: { attempt: number; id: string }) => `${item.attempt}:${item.id}`;
  if (!exact(review.mutants.map(mutantKey), template.mutants.map(mutantKey))) throw new Error('Every measured mutant must remain in the review, including unresolved mutants.');
  for (const item of review.coverage) for (const [nodes, measurement] of [[item.beforeNodes, report.measurements[0]], [item.afterNodes, report.measurements.at(-1)]] as const) {
    if (new Set(nodes).size !== nodes.length || nodes.some((node) => !measurement?.outcomes.some((outcome) => outcome.node === node))) throw new Error('Coverage annotations reference a missing executed test node.');
  }
}

export function scoreReports(items: { report: PythonReport; gold: Gold; review: Review; fault?: FaultProbe }[]) {
  return (['B0', 'B1', 'B2', 'B3'] as const).flatMap((variant) => {
    const runs = items.filter((item) => item.report.variant === variant);
    if (!runs.length) return [];
    const reviewed = runs.filter((item) => item.gold.reviewed && item.review.reviewed);
    const counts = { issues: [0, 0, 0], gaps: [0, 0, 0], inconsistencies: [0, 0, 0] };
    let behaviors = 0, beforeCovered = 0, afterCovered = 0, supported = 0, findings = 0, nonTestFailures = 0, incorrectRepairs = 0;
    const diagnosis = new Map<string, number[]>();
    const mutation = { before: [0, 0, 0], after: [0, 0, 0] };
    for (const { report, gold, review } of reviewed) {
      validateReview(report, gold, review);
      for (const key of ['issues', 'gaps', 'inconsistencies'] as const) {
        const expected = key === 'gaps' ? gold.behaviors.filter((item) => item.initialGap) : gold[key];
        const matched = new Set(review[key].flatMap((item) => item.match === null ? [] : [item.match]));
        counts[key][0] += matched.size; counts[key][1] += review[key].length - matched.size; counts[key][2] += expected.length - matched.size;
      }
