  const summary = [...new Set(rows.map(row => row.variant))].flatMap(variant => [...new Set(rows.map(row => row.challenge))].map(challenge => {
    const planned = rows.filter(row => row.variant === variant && row.challenge === challenge), observed = planned.filter(row => row.success !== null);
    return { variant, challenge, planned: planned.length, observed: observed.length, succeeded: observed.filter(row => row.success).length,
      successRate: observed.length === planned.length ? ratio(observed.filter(row => row.success).length, planned.length) : null,
      unresolved: planned.length - observed.length };
  }));
  return { scope: 'Controlled developer-seeded challenges, not natural-error frequency or independent semantic accuracy.',
    definitions: { recovery: 'Import/assertion challenges require an approved changed original artifact, passing generated execution and usable fixed-witness reference replay. Missing boundaries require corrected-copy fault detection. Valid failures require unchanged approved code plus corrected-copy detection.',
      missing: 'Missing/unusable runs stay in planned denominators and prevent a complete success rate.',
      validFailureDetectionLost: 'Observed loss of an initially detected seeded defect, not a general independently reviewed incorrect-repair rate.' }, rows, summary };
}

// Keep admission rejection separate from failures actually available to the diagnosis stage.
export function summarizeDiagnosisExposure(items: ExperimentItem[], references: Record<string, string>) {
  const rows = items.filter(item => references[item.entry.caseId] && ['B2', 'B3'].includes(item.entry.variant)).map(item => {
    const prepared = item.preparation?.report, measurement = prepared?.measurements.at(-1);
    const usable = prepared?.status === 'completed' && measurement?.integrity === true && !measurement.timedOut;
    const original = items.find(prefix => prefix.entry.caseId === item.entry.caseId && prefix.entry.repeat === item.entry.repeat && prefix.entry.variant === 'B1')?.report?.tests[0];
    const admitted = original && prepared?.tests.find(test => test.id === original.id);
    const exposed = usable && original ? !!admitted?.approved && measurement.outcomes.some(outcome => outcome.file === testFile(original.id, prepared!.runtime) && ['failed', 'error'].includes(outcome.status)) : null;
    const decisions = item.report?.diagnoses.filter(decision => (decision.phase || 'execution') === 'execution' && decision.testId === original?.id) || [];
    const category = exposed && decisions.length === 1 ? decisions[0].category : null;
    const current = item.report?.tests.find(test => test.id === original?.id);
    const complete = item.report?.status === 'completed';
    return { caseId: item.entry.caseId, variant: item.entry.variant, repeat: item.entry.repeat,
      referenceCategory: references[item.entry.caseId], preparationUsable: !!usable,
      originalAdmitted: usable && original ? !!admitted?.approved : null, runtimeFailureExposed: exposed,
      category, diagnosisBasis: item.report?.configuration?.configuredFeatures?.failureDiagnosis === false ? 'not_performed' : item.entry.variant === 'B2' ? 'unconditional_repair_baseline' : 'grounded_model_assessment',
      agreesWithFixtureReference: item.entry.variant === 'B3' && exposed && complete ? category === references[item.entry.caseId] : null,
      improvementStageRequests: item.report?.resources?.requests.filter(request => request.stage === 'Improve tests once').length ?? null,
      acceptedImprovements: complete ? item.report!.improvements.length : null,
      originalArtifactUnchanged: complete && original && current ? current.code === original.code && current.functionName === original.functionName && !!current.approved : null,
      status: item.report?.status || 'missing' };
  });
  return { scope: 'Developer-constructed runtime cases; expected categories are fixture references, not independent semantic labels. Admission is never bypassed. B2 categories are unconditional baseline decisions, not model classifications. No exposure means diagnosis agreement is unavailable, not successful diagnosis.', rows,
    summary: [...new Set(rows.map(row => row.variant))].map(variant => {
      const subset = rows.filter(row => row.variant === variant), exposed = subset.filter(row => row.runtimeFailureExposed === true);
      return { variant, planned: subset.length, runtimeExposed: exposed.length, admissionBlocked: subset.filter(row => row.originalAdmitted === false).length,
        preparationUnavailable: subset.filter(row => !row.preparationUsable).length,
        scoredFixtureDecisions: subset.filter(row => row.agreesWithFixtureReference !== null).length,
        matchesFixtureReference: subset.filter(row => row.agreesWithFixtureReference === true).length };
    }) };
}

import type { RequirementDocument, RequirementSource } from './requirements';

export const documentText = (document: RequirementDocument) => document.segments.map(segment => segment.text).join('\n\n');
type Span = { start: number; end: number };
type Rule = { id: string; text: string; originalId?: string; source?: RequirementSource; sources?: RequirementSource[] };

export function parseRequirementInput(input: string, document?: RequirementDocument) {
  const text = input.trim();
  if (!text) throw new Error('Enter requirements or upload a requirement file.');
  // Explicit identifiers establish input boundaries, not semantic correctness.
  const events = [...text.matchAll(/^[ \t]*(?:(?:#{1,6}[ \t]+)?(?:\|[ \t]*)?(?:\*\*)?((?:N?FR(?:-[A-Z0-9]+)*[- ]?\d+|R\d+))(?:\*\*)?(?=\s*[:.)|\-]|[ \t]+|$)|#{1,6}[ \t]+[^\r\n]+)/gmi)];
  const identified = events.some(event => event[1]);
  const groups: { originalId?: string; spans: Span[] }[] = [];
  const context: string[] = [];
  const span = (start: number, end: number) => {
    const content = text.slice(start, end), left = content.length - content.trimStart().length;
    return { start: start + left, end: end - (content.length - content.trimEnd().length) };
  };
  if (identified) {
    let cursor = 0;
    for (let i = 0; i < events.length; i++) {
      const event = events[i], start = event.index!;
      if (start > cursor) context.push(text.slice(cursor, start));
      const end = events[i + 1]?.index ?? text.length;
      if (event[1]) {
        const originalId = event[1].toUpperCase();
        let group = groups.find(group => group.originalId === originalId);
        if (!group) { group = { originalId, spans: [] }; groups.push(group); }
        group.spans.push(span(start, end));
      } else context.push(text.slice(start, end));
      cursor = end;
    }
  } else {
    let sections = text.split(/\n\s*\n/).filter(section => section.trim());
    if (sections.length === 1 && !document) sections = text.split(/\r?\n/).filter(section => section.trim());
    // Markdown headings name a section; they state no requirement of their own.
    const heading = (section: string) => section.trim().split(/\r?\n/).every(line => /^\s*#{1,6}\s/.test(line));
    const statements = sections.some(section => !heading(section));
    let cursor = 0;
    for (const section of sections) {
      const start = text.indexOf(section, cursor); cursor = start + section.length;
      if (statements && heading(section)) context.push(section);
      else groups.push({ spans: [span(start, cursor)] });
    }
  }
  const rules: Rule[] = groups.map((group, index) => {
    const content = group.spans.map(range => text.slice(range.start, range.end)).join('\n\n');
    const sources: RequirementSource[] = [];
    for (const segment of document?.segments || []) {
      const padded = '\n\n' + text + '\n\n', needle = '\n\n' + segment.text + '\n\n';
      const start = padded.indexOf(needle);
      // Edited or repeated source blocks have no unique exact location.
      if (!segment.text.trim() || start < 0 || padded.indexOf(needle, start + 1) >= 0) continue;
      for (const range of group.spans) {
        const overlap = span(Math.max(start, range.start), Math.min(start + segment.text.length, range.end));
        if (overlap.end <= overlap.start) continue;
        const quote = text.slice(overlap.start, overlap.end);
        sources.push({ documentId: document!.id, segmentId: segment.id, fileName: document!.fileName, sha256: document!.sha256,
          location: segment.location, page: segment.page, paragraph: segment.paragraph, line: segment.line,
          extraction: segment.extraction, confidence: segment.confidence, quote, start: overlap.start - start });
      }
    }
    const source = sources.length === 1 && sources[0].quote === content ? sources[0] : undefined;
    return { id: 'R' + (index + 1), text: content, ...(group.originalId ? { originalId: group.originalId } : {}), ...(source ? { source } : sources.length ? { sources } : {}) };
  });
  return { rules, mode: identified ? 'numbered' as const : 'text' as const, text, context: context.join('\n\n').trim() };
}

export const textRequirements = (input: string, document?: RequirementDocument) => parseRequirementInput(input, document).rules;
export const ruleSources = (rule: { source?: RequirementSource; sources?: RequirementSource[] }) => rule.sources || (rule.source ? [rule.source] : []);
export function sourceMatches(rule: Rule, source: RequirementSource, document: RequirementDocument) {
  const segment = document.segments.find(segment => segment.id === source.segmentId);
  const quote = source.quote || rule.text, start = source.start || 0;
  return source.documentId === document.id && source.sha256 === document.sha256 && !!quote && start >= 0 &&
    segment?.text.slice(start, start + quote.length) === quote && rule.text.includes(quote);
}

import { createHash, randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { z } from "zod";
import { dataDir } from "./auth";
import { dockerTool } from "./python-tools";

export const segmentSchema = z.object({ id: z.string(), text: z.string(), location: z.string(), page: z.number().int().positive().optional(), paragraph: z.number().int().positive().optional(), line: z.number().int().positive().optional(), extraction: z.enum(["ocr", "text"]).optional(), confidence: z.number().min(0).max(100).optional() });
export const pageSchema = z.object({ page: z.number().int().positive(), status: z.enum(["text", "ocr", "mixed", "partial", "unreadable", "failed", "skipped"]), detail: z.string(), confidence: z.number().min(0).max(100).optional() });
export type DocumentPage = z.infer<typeof pageSchema>;
export const documentSchema = z.object({ id: z.string().uuid(), fileName: z.string(), sha256: z.string(), format: z.enum(["pdf", "doc", "docx", "txt", "md"]), segments: z.array(segmentSchema), warnings: z.array(z.string()), pages: z.array(pageSchema).default([]) });
export type RequirementDocument = z.infer<typeof documentSchema>;
export type RequirementSource = { documentId: string; segmentId: string; fileName: string; sha256: string; location: string; page?: number; paragraph?: number; line?: number; extraction?: "ocr" | "text"; confidence?: number; quote?: string; start?: number };
export class DocumentIntegrityError extends Error {}
function directory(userId: string, id: string) {
  if (!z.string().uuid().safeParse(id).success) throw new Error("Invalid requirement document.");
  return join(dataDir, "documents", createHash("sha256").update(userId).digest("hex"), id);
}
export async function extractRequirements(userId: string, file: File, signal: AbortSignal) {
  const format = file.name.split(".").at(-1)?.toLowerCase();
  if (!["pdf", "doc", "docx", "txt", "md"].includes(format || "")) throw new Error("Use PDF, DOC, DOCX, TXT or Markdown.");
  if (!file.size || file.size > 10_000_000) throw new Error("Upload a nonempty requirement file up to 10 MB.");
  const id = randomUUID(), root = directory(userId, id), bytes = Buffer.from(await file.arrayBuffer());
  await mkdir(join(root, "source"), { recursive: true }); await mkdir(join(root, "generated"));
  try {
    const result = await dockerTool<{ segments?: RequirementDocument["segments"]; warnings?: string[]; pages?: DocumentPage[]; error?: string }>(root, { action: "document", format, data: bytes.toString("base64") }, signal);
    if (result.error) throw new Error(result.error);
    const document = documentSchema.parse({ id, format, fileName: file.name, sha256: createHash("sha256").update(bytes).digest("hex"), segments: result.segments, warnings: result.warnings, pages: result.pages });
    await writeFile(join(root, "original"), bytes, { mode: 0o600 });
    await writeFile(join(root, "document.json"), JSON.stringify(document), { mode: 0o600 });
    return document;
  } catch (error) { await rm(root, { recursive: true, force: true }); throw error; }
}
export async function loadRequirements(userId: string, id: string) {
  return (await originalRequirements(userId, id)).document;
}
export async function originalRequirements(userId: string, id: string) {
  const root = directory(userId, id);
  const [metadata, bytes] = await Promise.all([readFile(join(root, "document.json"), "utf8"), readFile(join(root, "original"))]);
  const document = documentSchema.parse(JSON.parse(metadata));
  if (document.id !== id || createHash("sha256").update(bytes).digest("hex") !== document.sha256) throw new DocumentIntegrityError("The saved requirement document failed its integrity check. Upload the original again.");
  return { document, bytes };
}
export function documentRules(document: RequirementDocument, ids: string[]) {
  if (!ids.length || new Set(ids).size !== ids.length) throw new Error("Select unique requirement blocks.");
  const selected = ids.map(id => { const segment = document.segments.find(item => item.id === id); if (!segment) throw new Error("Unknown requirement block."); return segment; });
  return selected.map((segment, index) => ({ id: "R" + (index + 1), text: segment.text, source: { documentId: document.id, segmentId: segment.id, fileName: document.fileName, sha256: document.sha256, location: segment.location, page: segment.page, paragraph: segment.paragraph, line: segment.line, extraction: segment.extraction, confidence: segment.confidence } as RequirementSource }));
}

import type { Measurement, PythonReport } from './python-types';
import { ruleSources } from './requirement-input';
import { testFile } from './runtime';
import { requirementCoverage } from './requirement-coverage';
import { mutationAssessmentMissing } from './verification-policy';
import { hasUninspectedContext } from './project-context';
import { findingEvidence } from './finding-evidence';

export const requirementStates = ['Verified', 'Partially Verified', 'Unverified', 'Uncertain', 'Pending'] as const;
export type RequirementState = typeof requirementStates[number];
export function agentStopReason(report: PythonReport) {
  if (report.status === 'running') return 'In progress: ' + report.stage;
  if (report.status !== 'completed') return report.error || report.testAttempts?.at(-1)?.error || 'The run ended before completion. Inspect the saved execution records.';
  return report.stopReason || 'No stopping decision was recorded for this older run. Inspect the saved tests and execution evidence.';
}
export function verificationGate(report: PythonReport, requireVerified = true) {
  const measured = report.measurements.at(-1), requirements = runEvaluation(report).requirements;
  return report.status === 'completed' && !report.resources?.exhausted && measured?.integrity === true && !measured.timedOut && measured.exitCode === 0 &&
    measured.outcomes.length > 0 && measured.outcomes.every(outcome => outcome.status === 'passed') && requirements.length > 0 &&
    requirements.every(rule => requireVerified ? rule.status === 'Verified' : !['Uncertain', 'Unverified', 'Pending'].includes(rule.status));
}
export function outcomeCounts(measurement?: Measurement) {
  return (['passed', 'failed', 'error', 'skipped'] as const).map(status => ({
    name: status === 'error' ? 'Errors' : status[0].toUpperCase() + status.slice(1),
    value: measurement?.outcomes.filter(outcome => outcome.status === status).length || 0,
  }));
}

export function verificationSummary(report: PythonReport) {
  const evaluation = runEvaluation(report), latest = evaluation.latest;
  const [passed, failed, errors, skipped] = evaluation.outcomes.map(item => item.value);
  const unmapped = evaluation.requirements.filter(rule => !rule.behaviors.length || rule.behaviors.every(behavior =>
    behavior.issue === 'not_testable' && behavior.gaps.includes('Behavior extraction incomplete.')));
  const unresolved = evaluation.requirements.filter(rule => rule.status !== 'Verified');
  // Execution progress is separate from the stricter verification policy.
  const trustedChecks = report.status === 'completed' && !report.resources?.exhausted && latest?.integrity === true && !latest.timedOut && [0, 1].includes(latest.exitCode) &&
    !report.collection?.timedOut && (!report.collection || [0, 5].includes(report.collection.exitCode));
  const checkItems = evaluation.requirements.map(rule => {
    const checked = !!trustedChecks && rule.behaviors.length > 0 && rule.behaviors.every(behavior => behavior.nodes.length > 0 && behavior.outcomes.every(outcome => ['passed', 'failed'].includes(outcome.status)) && behavior.nodes.every(node =>
      latest!.outcomes.some(outcome => outcome.node === node && ['passed', 'failed'].includes(outcome.status))));
    const investigate = checked && (rule.status === 'Uncertain' || rule.behaviors.some(behavior => behavior.outcomes.some(outcome => outcome.status === 'failed')));
    const label = report.status === 'running' ? 'In progress' : investigate ? 'Needs investigation' : checked ? 'Recorded checks passed' : rule.behaviors.some(behavior => behavior.outcomes.length) ? 'Checks incomplete' : 'Not checked';
    return { id: rule.id, checked, investigate, label };
  });
  const requirementChecks = { items: checkItems, checked: checkItems.filter(item => item.checked).length,
    passed: checkItems.filter(item => item.checked && !item.investigate).length,
    investigate: checkItems.filter(item => item.investigate).length,
    remaining: checkItems.filter(item => !item.checked).length };
  const needsAttention = evaluation.requirements.filter(rule => checkItems.some(item => item.id === rule.id && (!item.checked || item.investigate)) || !requirementCoverage(report, rule.id).complete);
  const checksPassedAwaitingAssurance = evaluation.requirements.filter(rule => rule.status !== 'Verified' && !needsAttention.some(item => item.id === rule.id) && checkItems.some(item => item.id === rule.id && item.checked && !item.investigate));
  const mutation = report.mutations.at(-1);
  const mutationAssessment = !mutation ? report.policy?.mutationChecks === false ? 'Not performed (not requested)' : 'Not performed'
    : mutation.incomplete || mutation.timedOut || mutation.mutants.some(item => item.status === 'unknown') ? 'Incomplete' : `Execution recorded (${mutation.mutants.length} mutants)`;
  const initialFailure = report.collection && (report.collection.timedOut || ![0, 5].includes(report.collection.exitCode)) ||
    report.baseline && (report.baseline.timedOut || report.baseline.integrity !== true || ![0, 5].includes(report.baseline.exitCode) || report.baseline.outcomes.some(outcome => ['failed', 'error'].includes(outcome.status)));
  const preserved = trustedChecks ? findingEvidence(report).filter(({ outcome, test, diagnosis }) => test && outcome.status === 'failed' &&
    report.tests.filter(active => active.id === test.id).length === 1 &&
    report.tests.some(active => active.id === test.id && active.approved && active.code === test.code) &&
    diagnosis?.category === 'potential_implementation_defect' && report.improvements.every(action =>
      !action.before.some(before => before.id === test.id && before.code !== test.code))).map(finding => finding.outcome) : [];
  let title = '', next = '';
  if (report.resources?.exhausted) { title = 'Model request budget reached'; next = 'Inspect the retained tests, reviews and execution evidence. This run is incomplete; a new run with an appropriate scope or budget is needed for unresolved checks.'; }
  else if (report.status === 'running') { title = 'Verification in progress'; next = 'Wait for the saved run to finish. Recorded results are provisional.'; }
  else if (report.status !== 'completed') { title = 'Run incomplete'; next = 'Inspect the saved error and execution records, correct the input or setup, then re-run.'; }
  else if (!latest?.outcomes.length) { title = 'No tests executed'; next = 'Inspect blocked tests and collection/setup errors. No passing result is available.'; }
  else if (latest.timedOut || latest.integrity !== true || ![0, 1].includes(latest.exitCode)) { title = 'Execution evidence incomplete'; next = 'Inspect time limits, integrity and execution errors before relying on the recorded outcomes.'; }
  else if (failed || errors) { title = `${failed + errors} ${failed + errors === 1 ? 'check needs' : 'checks need'} investigation`; next = 'Compare failing assertions and Agent diagnoses with the original requirements. A failure is not automatically a software defect.'; }
  else if (initialFailure) { title = 'Existing-test checks need attention'; next = 'Inspect collection and baseline diagnoses and logs. Later passing checks do not resolve earlier setup or existing-test failures.'; }
  else { title = `${passed} ${passed === 1 ? 'test' : 'tests'} passed${skipped ? `; ${skipped} skipped` : ''}`; next = 'Review unresolved behavior states and blocked tests. Passing cases do not establish complete specification coverage.'; }
  if (report.status === 'completed' && evaluation.blocked) next = `${evaluation.blocked} blocked test proposals need attention. Inspect their review reasons and uncovered requirements before regenerating. ` + next;
  if (report.replay) next += ' Saved-test execution does not regenerate analysis or diagnoses.';
  return { ...evaluation, passed, failedCount: failed, errors, skipped, unmapped, unresolved, preserved, requirementChecks, needsAttention, checksPassedAwaitingAssurance, mutationAssessment, title, next };
}

// Compare only changed artifacts against their own recorded executions, never a baseline suite.
export function improvementOutcomes(report: PythonReport) {
  if (report.replay || report.improvements.length !== 1) return [];
  const improvement = report.improvements[0];
  const status = (test: PythonReport['tests'][number] | undefined, measurement?: Measurement) => {
    if (!test?.approved) return 'Not executed';
    if (!measurement) return 'Awaiting execution';
    if (!measurement.integrity || measurement.timedOut || ![0, 1].includes(measurement.exitCode)) return 'Incomplete evidence';
    const outcomes = measurement.outcomes.filter(outcome => outcome.file === testFile(test.id, report.runtime) && outcome.name.split('[')[0] === test.functionName);
    if (!outcomes.length) return 'Not executed';
    if (new Set(outcomes.map(outcome => outcome.node)).size !== outcomes.length) return 'Incomplete evidence';
    if (outcomes.some(outcome => outcome.status === 'error')) return 'Error';
    if (outcomes.some(outcome => outcome.status === 'failed')) return 'Failed';
    if (outcomes.some(outcome => outcome.status === 'skipped')) return 'Skipped';
    return 'Passed';
  };
  return improvement.after.filter(test => improvement.after.filter(item => item.id === test.id).length === 1 &&
    improvement.before.filter(item => item.id === test.id).length <= 1 && !improvement.before.some(before => before.id === test.id &&
      before.code === test.code && before.approved === test.approved && before.functionName === test.functionName && before.behaviorId === test.behaviorId)).map(test => {
    const previous = improvement.before.find(before => before.id === test.id);
    const before = previous ? status(previous, report.measurements[0]) : 'Not proposed';
    const after = status(test, report.measurements.length === 2 ? report.measurements[1] : undefined);
    return { id: test.id, purpose: test.purpose, before, after, previous, test,
      recovered: ['Failed', 'Error'].includes(before) && after === 'Passed' };
  });
}

// Summarize saved assessments conservatively; this does not independently grade the agent.
export function runEvaluation(report: PythonReport) {
  const latest = report.measurements.at(-1);
  const requirements = report.rules.map(rule => {
    const behaviors = (report.analysis?.behaviors || []).filter(behavior => behavior.ruleId === rule.id).map(behavior => {
      const saved = report.states.find(state => state.id === behavior.id);
      const nodes = saved?.nodes || [];
      const outcomes = nodes.flatMap(node => latest?.outcomes.filter(outcome => outcome.node === node) || []);
      let status: RequirementState = saved?.status || 'Unverified';
      let reason = saved?.reason || 'No saved behavior assessment.';
      if (report.status === 'running') { status = 'Pending'; reason = 'This run has not finished.'; }
      else if (report.status !== 'completed' || report.resources?.exhausted || latest?.integrity === false || latest?.timedOut || report.collection?.timedOut || report.collection && ![0, 5].includes(report.collection.exitCode)) {
        status = 'Uncertain'; reason = 'The run or execution evidence is incomplete or interrupted.';
      } else if (behavior.issue !== 'none' || report.analysis?.inconsistencies.some(item => item.behaviorIds ? item.behaviorIds.includes(behavior.id) : item.ruleId === rule.id) || outcomes.some(outcome => ['failed', 'error'].includes(outcome.status))) {
        status = 'Uncertain'; reason = behavior.issue !== 'none' ? behavior.reason : 'Conflicting requirements or failing checks require investigation.';
      } else if (['Verified', 'Partially Verified'].includes(status) && (!latest || latest.integrity !== true || !nodes.length || nodes.some(node => !outcomes.some(outcome => outcome.node === node)))) {
        status = 'Uncertain'; reason = 'Mapped execution evidence is missing or integrity is not recorded.';
      } else if (status === 'Verified' && outcomes.some(outcome => outcome.status !== 'passed')) {
        status = 'Partially Verified'; reason = 'Some mapped checks did not pass.';
      } else if (status === 'Verified' && mutationAssessmentMissing(report, behavior.files)) {
        status = 'Partially Verified'; reason = 'Recorded checks passed; mutation adequacy was not assessed for every mapped source file.';
      } else if (status === 'Verified' && hasUninspectedContext(report.contextSelections, behavior.files)) {
        status = 'Partially Verified'; reason = 'A mapped source file or recorded local dependency remains uninspected.';
      } else if (status === 'Verified' && !requirementCoverage(report, rule.id).complete) {
        status = 'Partially Verified'; reason = requirementCoverage(report, rule.id).reason;
      }
      return { ...behavior, status, reason, nodes, outcomes };
    });
    const status: RequirementState = report.status === 'running' ? 'Pending' : report.status !== 'completed' || behaviors.some(item => item.status === 'Uncertain') ? 'Uncertain'
      : !behaviors.length ? 'Unverified' : behaviors.every(item => item.status === 'Verified') ? 'Verified'
      : behaviors.some(item => ['Verified', 'Partially Verified'].includes(item.status)) ? 'Partially Verified' : 'Unverified';
    return { ...rule, status, behaviors };
  });
  return {
    requirements, latest,
    distribution: requirementStates.map(name => ({ name, value: requirements.filter(rule => rule.status === name).length })),
    outcomes: outcomeCounts(latest),
    approved: report.tests.filter(test => test.approved).length,
    blocked: report.tests.filter(test => !test.approved).length,
    cited: report.rules.filter(rule => ruleSources(rule).some(source => source.documentId === report.requirementDocument?.id && source.sha256 === report.requirementDocument.sha256)).length,
    failed: latest?.outcomes.filter(outcome => ['failed', 'error'].includes(outcome.status)) || [],
  };
}

import type { PythonReport } from './python-types';
import { testFile } from './runtime';

// Join saved evidence only. Never assign a nearby test or an earlier diagnosis to a failure.
export function findingEvidence(report: PythonReport) {
  const phase = report.measurements.length > 1 ? 'remeasurement' : 'execution';
  // A replacement may be saved before re-execution finishes. Its code did not produce the first measurement.
  const artifacts = report.measurements.length === 1 ? report.improvements[0]?.before || report.tests : report.tests;
  return (report.measurements.at(-1)?.outcomes || []).filter(outcome => ['failed', 'error'].includes(outcome.status)).map(outcome => {
