    protocol: { ...(index.baselineProtocol ? { baselineProtocol: index.baselineProtocol, variantDefinitions: index.variantDefinitions } : {}), diagnosisAblation: manifest.diagnosisAblation || false, purpose: manifest.purpose || 'pilot', policyVersion: index.policyVersion ?? 'legacy_not_recorded', status: index.status, plannedRuns: index.expectedRuns, cases: manifest.cases.map(item => item.id), initialCandidates: manifest.cases.map(item => ({ id: item.id, source: item.initialTests ? 'seeded' : 'model' })), repeat: manifest.repeat, stabilityAssessed: manifest.repeat > 1, variants: manifest.variants, model: index.model, sandboxImage: index.sandboxImage, agentFingerprint: index.agentFingerprint, manifestHash: index.manifestHash, ...(paired ? { sharedInitialSuite: true, followupRequestLimit: manifest.followupRequestLimit, costScope: 'Follow-up rows exclude the shared prefix. Paired totals include B1 and any shared preparation once per strategy; actual billed totals must count each shared preparation once overall.' } : {}) },
